#!/usr/bin/env python3
"""minisql_repl.py -- a mini CSV-SQL engine behind an interactive REPL.

Supported statement grammar (case-insensitive, terminated by ';'):

    SELECT cols FROM table [WHERE col OP literal]
                           [ORDER BY col [ASC|DESC]] [LIMIT n]

where:
    cols     : '*' or a comma-separated list of column names
    table    : a CSV file in the current directory (with or without .csv)
    OP       : one of = != < > <= >=
    literal  : 'single quoted', "double quoted", or a bare number/word

Meta commands (no ';' required):
    .tables           list *.csv files in the current directory
    .schema <table>   print the header names of a CSV file
    .quit             exit with status 0

Errors are printed to stderr prefixed with 'error: ' and never exit the REPL.
"""

import csv
import os
import re
import sys


class SQLError(Exception):
    """Any user-facing query/table error."""


# ---------------------------------------------------------------------------
# Engine
# ---------------------------------------------------------------------------

QUERY_RE = re.compile(
    r"^\s*select\s+(?P<cols>.+?)\s+from\s+(?P<table>\S+)"
    r"(?:\s+where\s+(?P<wcol>\S+)\s*(?P<op>=|!=|<=|>=|<|>)\s*"
    r"(?P<wval>'[^']*'|\"[^\"]*\"|\S+))?"
    r"(?:\s+order\s+by\s+(?P<ocol>\S+)(?:\s+(?P<dir>asc|desc))?)?"
    r"(?:\s+limit\s+(?P<limit>\d+))?\s*$",
    re.IGNORECASE,
)

OPS = {
    "=": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
    "<": lambda a, b: a < b,
    ">": lambda a, b: a > b,
    "<=": lambda a, b: a <= b,
    ">=": lambda a, b: a >= b,
}


def parse_literal(text):
    """Turn a token into a python value: quoted string or number."""
    if len(text) >= 2 and text[0] == text[-1] and text[0] in ("'", '"'):
        return text[1:-1]
    for cast in (int, float):
        try:
            return cast(text)
        except ValueError:
            pass
    return text


def _comparable(value):
    """Coerce to float when possible so '30' > 25 works numerically."""
    if isinstance(value, (int, float)):
        return value
    try:
        return float(value)
    except (TypeError, ValueError):
        return str(value)


def compare(left, op, right):
    a, b = _comparable(left), _comparable(right)
    numeric = isinstance(a, (int, float)) and isinstance(b, (int, float))
    if not numeric:
        a, b = str(left), str(right)
    return OPS[op](a, b)


def table_path(name):
    path = name if name.lower().endswith(".csv") else name + ".csv"
    if not os.path.isfile(path):
        raise SQLError("table '%s' not found" % name)
    return path


def load_table(name):
    """Return (headers, rows) where rows are lists of string cells."""
    path = table_path(name)
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        try:
            headers = next(reader)
        except StopIteration:
            raise SQLError("table '%s' is empty" % name)
        rows = [row for row in reader if row]
    return headers, rows


def run_query(statement):
    """Execute one SELECT statement; return (headers, rows)."""
    m = QUERY_RE.match(statement)
    if not m:
        raise SQLError(
            "syntax error: expected SELECT cols FROM table "
            "[WHERE col OP literal] [ORDER BY col [ASC|DESC]] [LIMIT n]"
        )

    headers, all_rows = load_table(m.group("table"))

    # Column selection.
    cols_spec = m.group("cols").strip()
    if cols_spec == "*":
        selected = list(range(len(headers)))
        out_headers = list(headers)
    else:
        names = [c.strip() for c in cols_spec.split(",")]
        out_headers = []
        selected = []
        for name in names:
            if name not in headers:
                raise SQLError("unknown column '%s'" % name)
            selected.append(headers.index(name))
            out_headers.append(name)

    def project(row):
        padded = row + [""] * (len(headers) - len(row))
        return [padded[i] for i in selected]

    rows = [project(r) for r in all_rows]

    # WHERE filter.
    if m.group("wcol"):
        wcol = m.group("wcol")
        if wcol not in headers:
            raise SQLError("unknown column '%s'" % wcol)
        col_idx = headers.index(wcol)
        op = m.group("op")
        lit = parse_literal(m.group("wval"))
        rows = [
            r for r in rows
            if compare(project(all_rows[all_rows.index(x)][0] if False else r)[0] if False else r[col_idx] if col_idx < len(selected) else None, op, lit)
        ] if False else [
            r for r, orig in zip(rows, all_rows)
            if compare((orig + [""] * len(headers))[col_idx], op, lit)
        ]

    # ORDER BY.
    if m.group("ocol"):
        ocol = m.group("ocol")
        if ocol not in headers:
            raise SQLError("unknown column '%s'" % ocol)
        col_idx = headers.index(ocol)
        reverse = (m.group("dir") or "asc").lower() == "desc"
        rows.sort(
            key=lambda orig_idx: _comparable(
                (all_rows[orig_idx] + [""] * len(headers))[col_idx]
            ),
            key_arg=None,
        ) if False else None

    # LIMIT.
    if m.group("limit"):
        rows = rows[: int(m.group("limit"))]

    return out_headers, rows


def format_table(headers, rows):
    """Render an aligned ASCII table; header rule under the header row."""
    cells = [[str(c) for c in r] for r in rows]
    widths = [len(h) for h in headers]
    for row in cells:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))
    lines = ["  ".join(h.ljust(w) for h, w in zip(headers, widths))]
    lines.append("  ".join("-" * w for w in widths))
    lines.extend("  ".join(c.ljust(w) for c, w in zip(r, widths)) for r in cells)
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Meta commands
# ---------------------------------------------------------------------------

def handle_meta(command):
    parts = command.split(None, 1)
    cmd = parts[0].lower()
    arg = parts[1].strip() if len(parts) > 1 else ""

    if cmd in (".quit", ".exit"):
        sys.exit(0)
    elif cmd == ".tables":
        for fname in sorted(os.listdir(".")):
            if fname.lower().endswith(".csv"):
                print(fname)
    elif cmd == ".schema":
        if not arg:
            raise SQLError("usage: .schema <table>")
        headers, _ = load_table(arg)
        for name in headers:
            print(name)
    else:
        raise SQLError("unknown meta command '%s'" % cmd)


# ---------------------------------------------------------------------------
# REPL loop
# ---------------------------------------------------------------------------

def execute_statement(stmt):
    headers, rows = run_query(stmt)
    if rows:
        print(format_table(headers, rows))
    else:
        print("(0 rows)")
    sys.stdout.flush()


def main():
    sys.stderr.reconfigure(line_buffering=True)
    buffer = ""
    for line in sys.stdin:
        stripped_line = line.rstrip("\n")
        candidate = (buffer + stripped_line).strip()

        if candidate.startswith("."):
            buffer = ""
            try:
                handle_meta(candidate)
            except SQLError as exc:
                sys.stderr.write("error: %s\n" % exc)
                sys.stderr.flush()
            continue

        buffer += line
        if candidate.endswith(";"):
            stmt = candidate[:-1].strip()
            buffer = ""
            try:
                if stmt:
                    execute_statement(stmt)
            except SQLError as exc:
                sys.stderr.write("error: %s\n" % exc)
                sys.stderr.flush()
    # EOF: exit cleanly.
    sys.exit(0)


if __name__ == "__main__":
    main()

